INSERT INTO monster VALUES (298,'Dragon, True','Copper Dragon, Adult',NULL,'Large','Dragon','Earth','20d12+80 (210 hp)','+4','40 ft., fly 150 ft. (poor)','28 (-1 size, +19 natural), touch 9, flat-footed 28','+20','+30','Bite +26 (2d6+6) melee','Bite +26 (2d6+6) melee, 2 Claws +26 (1d8+3) melee, 2 Wings +25 (1d6+3) melee, Tail Slap +25 (1d8+9) melee','10 ft.','5 ft. (10 ft. with bite)','Breath weapon (40 ft. cone of slow gas or 80 ft. line of acid 12d4, DC 24), frightful presence (DC 23)','Blindsense 60 ft., damage reduction 5/magic, darkvision 120 ft., immunity to acid, immunity to sleep and paralysis, keen senses, spell resistance 21, spells (caster level 7th), spider climb, stone shape','Fort +16, Ref +12, Will +15','Str 23, Dex 10, Con 19, Int 16, Wis 17, Cha 16','Bluff +15, Concentration +16, Diplomacy +15, Escape Artist +12, Hide +8, Intimidate +15, Jump +18, Knowledge (any 2) +26, Listen +28, Search +26, Sense Motive +15, Spot +28, Use Magic Device +15',NULL,'Alertness, Empower Spell, Hover, Improved Initiative, Power Attack, Weapon Focus (bite), Weapon Focus (claw)',NULL,'Warm hills','Solitary, pair, or family (1-2 and 2-5 offspring)','14','Triple standard','Always chaotic good','21-22 HD (Large)','-','Blindsense (Ex), Breath Weapon (Su), Crush (Ex), Frightful Presence (Ex), Immunities (Ex), Keen Senses (Ex), Spell Resistance (Ex), Spider Climb (Ex), Tail Sweep (Ex)','Adult copper dragon; CR 14; Large dragon (earth); HD 20d12+80; hp 210; Init +4; Spd 40 ft., fly 150 ft. (poor); AC 28 (-1 size, +19 natural), touch 9, flat-footed 28; Base Atk +20; Grp +30; Atk +26 melee (2d6+6, bite); Full Atk +26 melee (2d6+6, bite) and +26 melee (1d8+3, 2 claws) and +25 melee (1d6+3, 2 wings) and +25 melee (1d8+9, tail slap); Space/Reach 10 ft./5 ft. (10 ft. with bite); SA Breath weapon (40 ft. cone of slow gas or 80 ft. line of acid 12d4, DC 24), frightful presence (DC 23); SQ Blindsense 60 ft., damage reduction 5/magic, darkvision 120 ft., immunity to acid, immunity to sleep and paralysis, keen senses, spell resistance 21, spells (caster level 7th), spider climb, stone shape; AL CG; SV Fort +16, Ref +12, Will +15; Str 23, Dex 10, Con 19, Int 16, Wis 17, Cha 16\n\nSkills and Feats: Bluff +15, Concentration +16, Diplomacy +15, Escape Artist +12, Hide +8, Intimidate +15, Jump +18, Knowledge (any 2) +26, Listen +28, Search +26, Sense Motive +15, Spot +28, Use Magic Device +15; Alertness, Empower Spell, Hover, Improved Initiative, Power Attack, Weapon Focus (bite), Weapon Focus (claw)','\n      <div topic=\"Copper Dragon\" level=\"4\"><p><h4>Copper Dragon</h4></p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td/><td><b>Copper Dragon, Adult</b><br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td/><td>Large Dragon (Earth)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Hit Dice:</b><br/></td><td>20d12+80 (210 hp)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Initiative:</b><br/></td><td>+4<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Speed:</b><br/></td><td>40 ft., fly 150 ft. (poor)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Armor Class:</b><br/></td><td>28 (-1 size, +19 natural), touch 9, flat-footed 28<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Base Attack/Grapple:</b><br/></td><td>+20/+30<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Attack:</b><br/></td><td>Bite +26 (2d6+6) melee<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Full Attack:</b><br/></td><td>Bite +26 (2d6+6) melee, 2 Claws +26 (1d8+3) melee, 2 Wings +25 (1d6+3) melee, Tail Slap +25 (1d8+9) melee<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Space/Reach:</b><br/></td><td>10 ft./5 ft. (10 ft. with bite)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Special Attacks:</b><br/></td><td>Breath weapon (40 ft. cone of slow gas or 80 ft. line of acid 12d4, DC 24), frightful presence (DC 23)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Special Qualities:</b><br/></td><td>Blindsense 60 ft., damage reduction 5/magic, darkvision 120 ft., immunity to acid, immunity to sleep and paralysis, keen senses, spell resistance 21, spells (caster level 7th), spider climb, <i>stone shape</i><br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Saves:</b><br/></td><td>Fort +16, Ref +12, Will +15<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Abilities:</b><br/></td><td>Str 23, Dex 10, Con 19, Int 16, Wis 17, Cha 16<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Skills:</b><br/></td><td>Bluff +15, Concentration +16, Diplomacy +15, Escape Artist +12, Hide +8, Intimidate +15, Jump +18, Knowledge (any 2) +26, Listen +28, Search +26, Sense Motive +15, Spot +28, Use Magic Device +15<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Feats:</b><br/></td><td>Alertness, Empower Spell, Hover, Improved Initiative, Power Attack, Weapon Focus (bite), Weapon Focus (claw)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Environment:</b><br/></td><td>Warm hills<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Organization:</b><br/></td><td>Solitary, pair, or family (1-2 and 2-5 offspring)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Challenge Rating:</b><br/></td><td>14<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Treasure:</b><br/></td><td>Triple standard<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Alignment:</b><br/></td><td>Always chaotic good<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Advancement:</b><br/></td><td>21-22 HD (Large)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Level Adjustment:</b><br/></td><td>-<br/></td></tr>\n\n</table><p/><p/><p/><div topic=\"Dragon\" level=\"8\"><p><b>Dragon (Earth)</b></p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment:</b> Warm hills</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Wyrmling, very young, young, juvenile, and young adult: solitary or clutch (2-5); adult, mature adult, old, very old, ancient, wyrm, or great wyrm: solitary, pair, or family (1-2 and 2-5 offspring)</p>\n</div><div topic=\"Challenge Ratings\" level=\"8\"><p><b>Challenge Ratings:</b> Wyrmling 3; very young 5; young 7; juvenile 9; young adult 11; adult 14; mature adult 16; old 19; very old 20; ancient 22; wyrm 23; great wyrm 25</p>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> Triple standard</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always chaotic good</p>\n</div><div topic=\"Advancement\" level=\"8\"><p><b>Advancement:</b> Wyrmling 6-7 HD; very young 9-10 HD; young 12-13 HD; juvenile 15-16 HD; young adult 18-19 HD; adult 21-22 HD; mature adult 24-25 HD; old 27-28 HD; very old 30-31 HD; ancient 33-34 HD; wyrm 36-37 HD; great wyrm 39+ HD</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> Wyrmling +2; very young +3; young +4; juvenile +4; others -</p><p/>\n</div><div topic=\"Copper Dragons by Age\" level=\"5\"><p><h5>Copper Dragons by Age</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"17\" curcol=\"17\">\n<td><b>Age</b><br/></td>\n<td><b>Size</b><br/></td>\n<td><b>Hit Dice (hp)</b><br/></td>\n<td><b>Str</b><br/></td>\n<td><b>Dex</b><br/></td>\n<td><b>Con</b><br/></td>\n<td><b>Int</b><br/></td>\n<td><b>Wis</b><br/></td>\n<td><b>Cha</b><br/></td>\n<td><b>Base Attack/</b><br/>\n<b>Grapple</b><br/></td> <td><b>Attack</b><br/></td>\n<td><b>Fort Save</b><br/></td>\n<td><b>Ref Save</b><br/></td>\n<td><b>Will Save</b><br/></td>\n<td><b>Breath Weapon (DC)</b><br/></td>\n<td><b>Frightful Presence DC</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"17\" curcol=\"17\">\n<td>Wyrmling<br/></td>\n<td>T<br/></td>\n<td>5d12+5 (37)<br/></td>\n<td>11<br/></td>\n<td>10<br/></td>\n<td>13<br/></td>\n<td>12<br/></td>\n<td>13<br/></td>\n<td>12<br/></td>\n<td>+5/-3<br/></td>\n<td>+7<br/></td>\n<td>+5<br/></td>\n<td>+4<br/></td>\n<td>+5<b